    <title>状态栏</title>
</head>
<body>
    <style>
        /* ===== 全局容器样式 ===== */
        .status-panel-container {
            font-family: 'Noto Sans SC', 'Microsoft YaHei', sans-serif;
            width: 100%;
            max-width: 420px;
            margin: 20px auto;
            border-radius: 12px;
            overflow: hidden;
            /* 双色系配色：深紫+暗金 */
            background: linear-gradient(135deg, #1a1625 0%, #2d2640 50%, #1a1625 100%);
            border: 1px solid rgba(212, 175, 55, 0.3);
            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.6), inset 0 1px 0 rgba(212, 175, 55, 0.1);
            /* 入场动画 */
            animation: panel-slide-in 0.6s cubic-bezier(0.22, 1, 0.36, 1);
        }

        @keyframes panel-slide-in {
            from {
                opacity: 0;
                transform: translateY(20px) scale(0.95);
            }
            to {
                opacity: 1;
                transform: translateY(0) scale(1);
            }
        }

        /* ===== 手风琴区块通用样式 ===== */
        .status-panel-container .accordion-section {
            border-bottom: 1px solid rgba(212, 175, 55, 0.15);
        }
        .status-panel-container .accordion-section:last-child {
            border-bottom: none;
        }

        .status-panel-container .accordion-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 12px 16px;
            cursor: pointer;
            background: rgba(45, 38, 64, 0.6);
            transition: all 0.3s ease;
            user-select: none;
        }
        .status-panel-container .accordion-header:hover {
            background: rgba(212, 175, 55, 0.1);
        }

        .status-panel-container .accordion-title {
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: 0.9em;
            font-weight: 600;
            color: #d4af37;
            text-shadow: 0 0 10px rgba(212, 175, 55, 0.3);
        }

        .status-panel-container .accordion-arrow {
            color: #d4af37;
            font-size: 0.8em;
            transition: transform 0.3s ease;
        }
        .status-panel-container .accordion-section.collapsed .accordion-arrow {
            transform: rotate(-90deg);
        }

        .status-panel-container .accordion-content {
            max-height: 500px;
            overflow: hidden;
            transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1), padding 0.3s ease;
            padding: 0 16px 16px 16px;
            background: rgba(26, 22, 37, 0.8);
        }
        .status-panel-container .accordion-section.collapsed .accordion-content {
            max-height: 0;
            padding: 0 16px;
        }

        /* ===== 内心想法区块 ===== */
        .status-panel-container .thought-list {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .status-panel-container .thought-item {
            display: flex;
            align-items: flex-start;
            gap: 10px;
            padding: 10px;
            background: rgba(45, 38, 64, 0.5);
            border-radius: 8px;
            border-left: 3px solid #d4af37;
            animation: thought-fade-in 0.5s ease forwards;
            opacity: 0;
        }
        .status-panel-container .thought-item:nth-child(1) { animation-delay: 0.1s; }
        .status-panel-container .thought-item:nth-child(2) { animation-delay: 0.2s; }
        .status-panel-container .thought-item:nth-child(3) { animation-delay: 0.3s; }
        .status-panel-container .thought-item:nth-child(4) { animation-delay: 0.4s; }
        .status-panel-container .thought-item:nth-child(5) { animation-delay: 0.5s; }

        @keyframes thought-fade-in {
            from {
                opacity: 0;
                transform: translateX(-10px);
            }
            to {
                opacity: 1;
                transform: translateX(0);
            }
        }

        .status-panel-container .thought-name {
            flex-shrink: 0;
            padding: 2px 8px;
            background: linear-gradient(135deg, #d4af37, #b8960c);
            color: #1a1625;
            font-size: 0.75em;
            font-weight: 700;
            border-radius: 4px;
        }

        .status-panel-container .thought-text {
            color: #c9c5d4;
            font-size: 0.85em;
            line-height: 1.5;
            font-style: italic;
        }
        .status-panel-container .thought-text::before {
            content: '"';
            color: #d4af37;
        }
        .status-panel-container .thought-text::after {
            content: '"';
            color: #d4af37;
        }

        /* ===== 翻转卡片：User吐槽 ===== */
        .status-panel-container .flip-card-container {
            perspective: 1000px;
            width: 100%;
            height: 80px;
            margin-top: 5px;
        }

        .status-panel-container .flip-card {
            width: 100%;
            height: 100%;
            position: relative;
            transform-style: preserve-3d;
            transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
            cursor: pointer;
        }
        .status-panel-container .flip-card:hover {
            transform: rotateY(180deg);
        }

        .status-panel-container .flip-card-front,
        .status-panel-container .flip-card-back {
            position: absolute;
            width: 100%;
            height: 100%;
            backface-visibility: hidden;
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 12px;
            box-sizing: border-box;
        }

        .status-panel-container .flip-card-front {
            background: linear-gradient(135deg, #2d2640, #3d3555);
            border: 1px dashed rgba(212, 175, 55, 0.4);
        }
        .status-panel-container .flip-card-front span {
            color: #888;
            font-size: 0.8em;
        }

        .status-panel-container .flip-card-back {
            background: linear-gradient(135deg, #4a1942, #2d1a2e);
            border: 1px solid rgba(255, 100, 150, 0.3);
            transform: rotateY(180deg);
        }
        .status-panel-container .flip-card-back .user-complaint {
            color: #ffb6c1;
            font-size: 0.85em;
            text-align: center;
            line-height: 1.5;
        }
        .status-panel-container .flip-card-back .user-complaint::before {
            content: '💢 ';
        }

        /* ===== 商品推荐区块 ===== */
        .status-panel-container .product-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 12px;
        }

        .status-panel-container .product-card {
            background: rgba(45, 38, 64, 0.6);
            border-radius: 8px;
            padding: 12px;
            border: 1px solid rgba(212, 175, 55, 0.2);
            transition: all 0.3s ease;
            animation: product-pop-in 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
            opacity: 0;
        }
        .status-panel-container .product-card:nth-child(1) { animation-delay: 0.2s; }
        .status-panel-container .product-card:nth-child(2) { animation-delay: 0.35s; }

        @keyframes product-pop-in {
            from {
                opacity: 0;
                transform: scale(0.8);
            }
            to {
                opacity: 1;
                transform: scale(1);
            }
        }

        .status-panel-container .product-card:hover {
            transform: translateY(-3px);
            border-color: rgba(212, 175, 55, 0.5);
            box-shadow: 0 6px 20px rgba(212, 175, 55, 0.15);
        }

        .status-panel-container .product-name {
            color: #d4af37;
            font-size: 0.85em;
            font-weight: 600;
            margin-bottom: 6px;
            display: flex;
            align-items: center;
            gap: 5px;
        }
        .status-panel-container .product-name::before {
            content: '🏷️';
            font-size: 0.9em;
        }

        .status-panel-container .product-desc {
            color: #a09aaf;
            font-size: 0.75em;
            line-height: 1.4;
            margin-bottom: 8px;
        }

        .status-panel-container .product-price {
            display: inline-block;
            background: linear-gradient(135deg, #d4af37, #f0c850);
            color: #1a1625;
            font-size: 0.7em;
            font-weight: 700;
            padding: 3px 8px;
            border-radius: 10px;
        }

        /* ===== 空状态隐藏 ===== */
        .status-panel-container .thought-item:empty,
        .status-panel-container .thought-item:has(.thought-name:empty) {
            display: none;
        }
    </style>

    <div class="status-panel-container">
        <!-- 内心想法区块 -->
        <div class="accordion-section" id="thoughts-section">
            <div class="accordion-header" onclick="toggleAccordion('thoughts-section')">
                <div class="accordion-title">
                    <span>💭</span>
                    <span>内心独白</span>
                </div>
                <span class="accordion-arrow">▼</span>
            </div>
            <div class="accordion-content">
                <div class="thought-list">
                    <!-- 人物1 -->
                    <div class="thought-item">
                        <span class="thought-name">$1</span>
                        <span class="thought-text">$2</span>
                    </div>
                    <!-- 人物2 -->
                    <div class="thought-item">
                        <span class="thought-name">$3</span>
                        <span class="thought-text">$4</span>
                    </div>
                    <!-- 人物3 -->
                    <div class="thought-item">
                        <span class="thought-name">$5</span>
                        <span class="thought-text">$6</span>
                    </div>
                    <!-- 人物4 -->
                    <div class="thought-item">
                        <span class="thought-name">$7</span>
                        <span class="thought-text">$8</span>
                    </div>
                    <!-- 人物5 -->
                    <div class="thought-item">
                        <span class="thought-name">$9</span>
                        <span class="thought-text">$10</span>
                    </div>
                </div>

                <!-- 翻转卡片：User吐槽 -->
                <div class="flip-card-container">
                    <div class="flip-card">
                        <div class="flip-card-front">
                            <span>🔮 悬停查看穿越者内心...</span>
                        </div>
                        <div class="flip-card-back">
                            <div class="user-complaint">$11</div>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <!-- 商品推荐区块 -->
        <div class="accordion-section" id="products-section">
            <div class="accordion-header" onclick="toggleAccordion('products-section')">
                <div class="accordion-title">
                    <span>🛒</span>
                    <span>今日好物</span>
                </div>
                <span class="accordion-arrow">▼</span>
            </div>
            <div class="accordion-content">
                <div class="product-grid">
                    <!-- 商品1 -->
                    <div class="product-card">
                        <div class="product-name">$12</div>
                        <div class="product-desc">$13</div>
                        <span class="product-price">$14</span>
                    </div>
                    <!-- 商品2 -->
                    <div class="product-card">
                        <div class="product-name">$15</div>
                        <div class="product-desc">$16</div>
                        <span class="product-price">$17</span>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <script>
        // 手风琴折叠/展开功能
        function toggleAccordion(sectionId) {
            const section = document.getElementById(sectionId);
            if (section) {
                section.classList.toggle('collapsed');
            }
        }

        // 页面加载时隐藏空的thought-item
        document.addEventListener('DOMContentLoaded', function() {
            const thoughtItems = document.querySelectorAll('.status-panel-container .thought-item');
            thoughtItems.forEach(item => {
                const nameEl = item.querySelector('.thought-name');
                const textEl = item.querySelector('.thought-text');
                // 如果名字为空或只有引号，隐藏该项
                if (!nameEl || !nameEl.textContent.trim() || !textEl || textEl.textContent.trim() === '""') {
                    item.style.display = 'none';
                }
            });
        });
    </script>
</body>
</html>
